    if '#' in to_parse:
        to_parse = dep.line.split('#')[0]

    for req_hash in dep.hashes:
        to_parse = to_parse.replace(req_hash, '')

    to_parse = to_parse.replace('\\', '').rstrip()

    try:
        # Try to build a PEP Requirement from the cleaned line
